#!/usr/bin/env python3import reimport statistics as statsimport sysfrom pathlib import PathTEST_RE = re.compile(r"Test result for ([^:]+): accuracy=([0-9.]+), f1=([0-9.]+)")def parse_name(path):    name = path.name    if name.startswith("source_gpu"):        stem = name[:-4]        rest = stem.split("_", 2)[2]        task, suffix = rest.split("_seed", 1)        seed_text, config = suffix.split("_", 1)        return {"kind": "source", "task": task, "seed": int(seed_text), "config": config}    if name.startswith("timematch_gpu"):        stem = name[:-4]        rest = stem.split("_", 2)[2]        task, suffix = rest.split("_seed", 1)        seed_text, suffix = suffix.split("_", 1)        config, epoch_text = suffix.rsplit("_epoch", 1)        return {            "kind": "timematch",            "task": task,            "seed": int(seed_text),            "config": config,            "source_epoch": int(epoch_text),        }    return {"kind": "unknown", "task": path.stem, "seed": -1, "config": "unknown"}def parse_kv_line(line, prefix):    out = {}    for part in line[len(prefix):].strip().split("|"):        if "=" not in part:            continue        key, value = part.split("=", 1)        out[key] = value    return outdef safe_float(value):    if value is None or value == "":        return None    try:        return float(value)    except ValueError:        return Nonedef safe_int(value):    if value is None or value == "":        return None    try:        return int(float(value))    except ValueError:        return Nonedef fmt(value):    if value is None:        return ""    if isinstance(value, float):        return f"{value:.6f}"    return str(value)def write_tsv(path, rows, fields):    with path.open("w", encoding="utf-8", newline="\n") as handle:        handle.write("\t".join(fields) + "\n")        for row in rows:            handle.write("\t".join(fmt(row.get(field)) for field in fields) + "\n")def mean(values):    values = [value for value in values if value is not None]    return None if not values else sum(values) / len(values)def stdev(values):    values = [value for value in values if value is not None]    return None if len(values) < 2 else stats.stdev(values)def corr(xs, ys):    pairs = [        (x, y)        for x, y in zip(xs, ys)        if x is not None and y is not None    ]    if len(pairs) < 2:        return None    mx = sum(x for x, _ in pairs) / len(pairs)    my = sum(y for _, y in pairs) / len(pairs)    vx = sum((x - mx) ** 2 for x, _ in pairs)    vy = sum((y - my) ** 2 for _, y in pairs)    if vx <= 0.0 or vy <= 0.0:        return None    cov = sum((x - mx) * (y - my) for x, y in pairs)    return cov / (vx * vy) ** 0.5def delta(left, right):    if left is None or right is None:        return None    return left - rightdef parse_source_log(path):    info = parse_name(path)    text = path.read_text(encoding="utf-8", errors="ignore")    status = "ok"    if "Traceback" in text or "error:" in text.lower():        status = "error"    rows = []    for line in text.splitlines():        if not line.startswith("SOURCE_EPOCH_SUMMARY|"):            continue        values = parse_kv_line(line, "SOURCE_EPOCH_SUMMARY|")        rows.append(            {                "task": info["task"],                "seed": info["seed"],                "config": info["config"],                "source_epoch": safe_int(values.get("epoch")),                "source_loss": safe_float(values.get("loss")),                "source_cls": safe_float(values.get("cls")),                "source_compact": safe_float(values.get("compact")),                "source_compact_raw": safe_float(values.get("compact_raw")),                "source_compact_reshaped": safe_float(values.get("compact_reshaped")),                "structure_target": values.get("target"),                "structure_detached": values.get("detached"),                "status": status,                "log": path.name,            }        )    if not rows:        rows.append(            {                "task": info["task"],                "seed": info["seed"],                "config": info["config"],                "source_epoch": None,                "status": "incomplete" if status == "ok" else status,                "log": path.name,            }        )    return rowsdef parse_timematch_log(path):    info = parse_name(path)    text = path.read_text(encoding="utf-8", errors="ignore")    tests = TEST_RE.findall(text)    pseudo_rows = [        parse_kv_line(line, "TIMEMATCH_PSEUDO_SUMMARY|")        for line in text.splitlines()        if line.startswith("TIMEMATCH_PSEUDO_SUMMARY|")    ]    status = "ok"    if "Traceback" in text or "error:" in text.lower():        status = "error"    if not tests:        status = "incomplete" if status == "ok" else status    initial = next((row for row in pseudo_rows if row.get("stage") == "initial"), {})    train_rows = [row for row in pseudo_rows if row.get("stage") == "train_epoch"]    epoch1 = train_rows[0] if train_rows else {}    best_all = max((safe_float(row.get("all_f1")) or 0.0 for row in train_rows), default=None)    best_masked = max((safe_float(row.get("masked_f1")) or 0.0 for row in train_rows), default=None)    da_f1 = safe_float(tests[-1][2]) if tests else None    da_acc = safe_float(tests[-1][1]) if tests else None    return {        "task": info["task"],        "seed": info["seed"],        "config": info["config"],        "source_epoch": info["source_epoch"],        "da_acc": da_acc,        "da_f1": da_f1,        "initial_shift": safe_int(initial.get("shift")),        "initial_all_f1": safe_float(initial.get("all_f1")),        "initial_masked_f1": safe_float(initial.get("masked_f1")),        "initial_coverage": safe_float(initial.get("coverage")),        "initial_mean_conf": safe_float(initial.get("mean_conf")),        "epoch1_shift": safe_int(epoch1.get("shift")),        "epoch1_all_f1": safe_float(epoch1.get("all_f1")),        "epoch1_masked_f1": safe_float(epoch1.get("masked_f1")),        "epoch1_coverage": safe_float(epoch1.get("coverage")),        "epoch1_mean_conf": safe_float(epoch1.get("mean_conf")),        "best_epoch_all_f1": best_all,        "best_epoch_masked_f1": best_masked,        "pseudo_summary_count": len(pseudo_rows),        "status": status,        "log": path.name,    }def attach_source_rows(timematch_rows, source_rows):    source_by_key = {        (row["task"], row["seed"], row["config"], row["source_epoch"]): row        for row in source_rows        if row.get("source_epoch") is not None    }    out = []    for row in timematch_rows:        merged = dict(row)        source = source_by_key.get(            (row["task"], row["seed"], row["config"], row["source_epoch"]),            {},        )        for key in [            "source_loss",            "source_cls",            "source_compact",            "source_compact_raw",            "source_compact_reshaped",            "structure_target",            "structure_detached",        ]:            merged[key] = source.get(key)        out.append(merged)    return outdef build_contrasts(rows, base_config, shaped_config):    by_key = {        (row["task"], row["seed"], row["source_epoch"], row["config"]): row        for row in rows        if row.get("status") == "ok"    }    pairs = sorted({(task, seed, epoch) for task, seed, epoch, _ in by_key})    fields = [        "source_loss",        "source_cls",        "source_compact",        "da_f1",        "initial_all_f1",        "initial_masked_f1",        "initial_coverage",        "initial_mean_conf",        "epoch1_all_f1",        "epoch1_masked_f1",        "epoch1_coverage",        "epoch1_mean_conf",        "best_epoch_all_f1",        "best_epoch_masked_f1",    ]    out = []    for task, seed, epoch in pairs:        base = by_key.get((task, seed, epoch, base_config))        shaped = by_key.get((task, seed, epoch, shaped_config))        if base is None or shaped is None:            continue        row = {            "task": task,            "seed": seed,            "source_epoch": epoch,            "base_config": base_config,            "shaped_config": shaped_config,            "base_initial_shift": base.get("initial_shift"),            "shaped_initial_shift": shaped.get("initial_shift"),            "base_epoch1_shift": base.get("epoch1_shift"),            "shaped_epoch1_shift": shaped.get("epoch1_shift"),        }        for field in fields:            row[f"base_{field}"] = base.get(field)            row[f"shaped_{field}"] = shaped.get(field)            row[f"delta_{field}"] = delta(shaped.get(field), base.get(field))        out.append(row)    return outdef summarize(rows, group_fields, value_fields):    grouped = {}    for row in rows:        key = tuple(row.get(field) for field in group_fields)        grouped.setdefault(key, []).append(row)    out = []    for key, group in sorted(grouped.items()):        item = {field: value for field, value in zip(group_fields, key)}        item["n"] = len(group)        for field in value_fields:            values = [row.get(field) for row in group]            item[f"{field}_mean"] = mean(values)            item[f"{field}_std"] = stdev(values)            item[f"{field}_pos"] = sum(value is not None and value > 0 for value in values)        out.append(item)    return outdef build_alignment(rows):    grouped = {}    for row in rows:        grouped.setdefault(row["task"], []).append(row)    fields = [        "delta_initial_all_f1",        "delta_initial_masked_f1",        "delta_initial_coverage",        "delta_epoch1_all_f1",        "delta_epoch1_masked_f1",        "delta_epoch1_coverage",        "delta_best_epoch_all_f1",        "delta_best_epoch_masked_f1",    ]    out = []    for task, group in sorted(grouped.items()):        item = {"task": task, "n": len(group)}        da_values = [row.get("delta_da_f1") for row in group]        item["delta_da_f1_mean"] = mean(da_values)        for field in fields:            item[f"corr_da_vs_{field}"] = corr(da_values, [row.get(field) for row in group])            item[f"{field}_mean"] = mean([row.get(field) for row in group])        out.append(item)    return outdef main():    if len(sys.argv) not in {2, 4}:        raise SystemExit(            "Usage: summarize_v243b_readiness_checkpoint_causal.py LOG_DIR [BASE_CONFIG SHAPED_CONFIG]"        )    root = Path(sys.argv[1])    base_config = sys.argv[2] if len(sys.argv) == 4 else "plain"    shaped_config = sys.argv[3] if len(sys.argv) == 4 else "raw_global_w1_source_only"    source_rows = []    for path in sorted(root.glob("source_gpu*.log")):        source_rows.extend(parse_source_log(path))    timematch_rows = [        parse_timematch_log(path)        for path in sorted(root.glob("timematch_gpu*.log"))    ]    joined_rows = attach_source_rows(timematch_rows, source_rows)    contrasts = build_contrasts(joined_rows, base_config, shaped_config)    source_fields = [        "task",        "seed",        "config",        "source_epoch",        "source_loss",        "source_cls",        "source_compact",        "source_compact_raw",        "source_compact_reshaped",        "structure_target",        "structure_detached",        "status",        "log",    ]    write_tsv(root / "readiness_checkpoint_source.tsv", source_rows, source_fields)    row_fields = [        "task",        "seed",        "config",        "source_epoch",        "source_loss",        "source_cls",        "source_compact",        "da_acc",        "da_f1",        "initial_shift",        "initial_all_f1",        "initial_masked_f1",        "initial_coverage",        "initial_mean_conf",        "epoch1_shift",        "epoch1_all_f1",        "epoch1_masked_f1",        "epoch1_coverage",        "epoch1_mean_conf",        "best_epoch_all_f1",        "best_epoch_masked_f1",        "pseudo_summary_count",        "status",        "log",    ]    write_tsv(root / "readiness_checkpoint_timematch.tsv", joined_rows, row_fields)    contrast_fields = list(contrasts[0].keys()) if contrasts else []    write_tsv(root / "readiness_checkpoint_contrasts.tsv", contrasts, contrast_fields)    value_fields = [        "delta_da_f1",        "delta_initial_all_f1",        "delta_initial_masked_f1",        "delta_initial_coverage",        "delta_initial_mean_conf",        "delta_epoch1_all_f1",        "delta_epoch1_masked_f1",        "delta_epoch1_coverage",        "delta_epoch1_mean_conf",        "delta_best_epoch_all_f1",        "delta_best_epoch_masked_f1",    ]    by_task_epoch = summarize(        contrasts,        ["task", "source_epoch"],        value_fields,    )    write_tsv(        root / "readiness_checkpoint_summary_by_task_epoch.tsv",        by_task_epoch,        ["task", "source_epoch", "n"]        + [item for field in value_fields for item in (f"{field}_mean", f"{field}_std", f"{field}_pos")],    )    by_task = summarize(contrasts, ["task"], value_fields)    write_tsv(        root / "readiness_checkpoint_summary_by_task.tsv",        by_task,        ["task", "n"]        + [item for field in value_fields for item in (f"{field}_mean", f"{field}_std", f"{field}_pos")],    )    alignment = build_alignment(contrasts)    alignment_fields = list(alignment[0].keys()) if alignment else []    write_tsv(root / "readiness_checkpoint_alignment.tsv", alignment, alignment_fields)    print("Wrote:", root / "readiness_checkpoint_source.tsv")    print("Wrote:", root / "readiness_checkpoint_timematch.tsv")    print("Wrote:", root / "readiness_checkpoint_contrasts.tsv")    print("Wrote:", root / "readiness_checkpoint_summary_by_task_epoch.tsv")    print("Wrote:", root / "readiness_checkpoint_summary_by_task.tsv")    print("Wrote:", root / "readiness_checkpoint_alignment.tsv")if __name__ == "__main__":    main()